commands:
mkdir -p /tmp/incident-backup && kubectl -n otel-demo get configmap recommendation-config -o yaml > /tmp/incident-backup/recommendation-config.yaml && kubectl -n otel-demo get deploy recommendation -o yaml > /tmp/incident-backup/recommendation-deploy.yaml && kubectl -n otel-demo patch configmap recommendation-config --type merge -p "$(cat <<'EOF'
{"data":{"config":"{
    "configuration_items": [
        {
            "name": "fake"
        }
    ]
}
"}}
EOF
)" && kubectl -n otel-demo get configmap recommendation-config -o jsonpath='{.data.config}' | python3 -c 'import json,sys; print("valid JSON:", json.load(sys.stdin))'
